1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Quote: simplest cases -------------------------------------------------
6	  it("empty item list → premium 5 G (only the processing fee)", () => {
7	    const scenario = {
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    };
11	
12	    expect(runScenario(scenario)).toEqual({ results: [{ premium: 5 }] });
13	  });
14	  it.todo("a single plain sword → premium 115 G (100 base + 10 first insurance + 5 fee)");
15	  it.todo("a single plain amulet → premium 71 G (60 base + 6 first insurance + 5 fee)");
16	  it.todo("a single plain staff → premium 93 G (80 base + 8 first insurance + 5 fee)");
17	  it.todo("a single plain potion → premium 49 G (40 base + 4 first insurance + 5 fee)");
18	
19	  // --- Components and blocks -------------------------------------------------
20	  it.todo("a single rune → base premium 25 G");
21	  it.todo("2 runes → 50 G base premium");
22	  it.todo("3 runes → 60 G base premium (block applies)");
23	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
24	  it.todo("7 runes → 175 G base premium");
25	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
26	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
27	
28	  // --- Individual premium modifiers -----------------------------------------
29	  it.todo("cursed items add a 50 % risk surcharge to the item's base premium");
30	  it.todo("enchantment level 5 adds a 30 % high-enchantment surcharge");
31	  it.todo("enchantment level 4 adds no high-enchantment surcharge");
32	  it.todo("a cursed sword with exactly enchantment 5 gets both surcharges");
33	  it.todo("a customer with exactly 2 years with MHPCO gets the 20 % loyalty discount");
34	  it.todo("a customer with 1 year with MHPCO gets no loyalty discount");
35	  it.todo("the second contract of a scenario gets the 15 % follow-up discount");
36	
37	  // --- Modifier scope on multi-item policies --------------------------------
38	  it.todo(
39	    "cursed sword (100 G) + plain amulet (60 G) → curse adds 50 G on the item only → 210 G before further modifiers and fee",
40	  );
41	
42	  // --- Rounding --------------------------------------------------------------
43	  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
44	  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
45	
46	  // --- Claim: standard reimbursement ----------------------------------------
47	  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
48	  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
49	
50	  // --- Claim: special clauses ------------------------------------------------
51	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
52	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
53	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
54	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
55	
56	  // --- Claim: deductible per damage event -----------------------------------
57	  it.todo(
58	    "dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)",
59	  );
60	
61	  // --- Cap -------------------------------------------------------------------
62	  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
63	  it.todo("a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
64	  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G");
65	  it.todo("two swords → insurance sum 2000 G, cap 4000 G");
66	  it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
67	  it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
68	
69	  // --- Multiple items of the same type --------------------------------------
70	  it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
71	  it.todo("more damage entries of a type than insured → error (non-zero exit)");
72	
73	  // --- Error cases -----------------------------------------------------------
74	  it.todo("quote with an unknown item type (broomstick) → error");
75	  it.todo("claim referencing an item not part of the policy → error");
76	  it.todo("claim with a damage entry of an unknown item type → error");
77	  it.todo("claim with a damage entry amount -200 → error");
78	
79	  // --- Integration examples --------------------------------------------------
80	  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
81	  it.todo("3-year customer's second quote, cursed sword enchantment 7 → premium 160 G");
82	
83	  // --- CLI -------------------------------------------------------------------
84	  it.todo("CLI reads the schema example from stdin and writes results to stdout");
85	  it.todo("CLI exits non-zero and writes to stderr on an unknown item type, with no results on stdout");
86	});
